# Analyze the tool call sequences - what are the most common 3-step patterns?
python3 << 'EOF'
import json, os
from collections import Counter

sessions_dir = ".state/sessions/history"
sids = sorted(os.listdir(sessions_dir), key=lambda x: os.path.getmtime(f"{sessions_dir}/{x}"), reverse=True)[:60]

three_grams = Counter()
four_grams = Counter()
agent_sequences = {}

for sid in sids:
    jsonl = f"{sessions_dir}/{sid}/session.jsonl"
    meta = f"{sessions_dir}/{sid}/meta.json"
    if not os.path.exists(jsonl) or not os.path.exists(meta):
        continue

    with open(meta) as f:
        m = json.load(f)
    agent = m.get('agent', '')

    tools = []
    with open(jsonl) as fh:
        for line in fh:
            try:
                d = json.loads(line)
                if d.get('role') == 'assistant' and d.get('content'):
                    for item in (d.get('content') or []):
                        if item.get('type') == 'toolCall':
                            tools.append(item.get('name','?'))
            except:
                pass

    if agent not in agent_sequences:
        agent_sequences[agent] = []
    agent_sequences[agent].append(tools)

    for i in range(len(tools)-2):
        three_grams[tuple(tools[i:i+3])] += 1
    for i in range(len(tools)-3):
        four_grams[tuple(tools[i:i+4])] += 1

print("=== Top 3-grams (across all agents) ===")
for gram, count in three_grams.most_common(15):
    print(f"  {count}x: {' → '.join(gram)}")

print("\n=== Top 4-grams ===")
for gram, count in four_grams.most_common(10):
    print(f"  {count}x: {' → '.join(gram)}")

# Specifically look for edit-related patterns
print("\n=== Edit-related 3-grams ===")
for gram, count in three_grams.most_common(100):
    if 'edit' in gram or 'write' in gram:
        print(f"  {count}x: {' → '.join(gram)}")
EOF

