# Let me look at a broader view - ALL sessions (not just coder) that do edits
# What's the "verify after edit" pattern like?
python3 << 'EOF'
import json, os

sessions_dir = ".state/sessions/history"
sids = sorted(os.listdir(sessions_dir), key=lambda x: os.path.getmtime(f"{sessions_dir}/{x}"), reverse=True)[:60]

agent_stats = {}

for sid in sids:
    jsonl = f"{sessions_dir}/{sid}/session.jsonl"
    meta = f"{sessions_dir}/{sid}/meta.json"
    if not os.path.exists(jsonl) or not os.path.exists(meta):
        continue

    with open(meta) as f:
        m = json.load(f)
    agent = m.get('agent', '')

    tools = []
    with open(jsonl) as fh:
        for line in fh:
            try:
                d = json.loads(line)
                if d.get('role') == 'assistant' and d.get('content'):
                    for item in (d.get('content') or []):
                        if item.get('type') == 'toolCall':
                            tools.append(item.get('name','?'))
            except:
                pass

    if 'edit' not in tools and 'write' not in tools:
        continue

    if agent not in agent_stats:
        agent_stats[agent] = {'sessions': 0, 'edits_total': 0, 'verify_after': 0, 'no_verify': 0, 'read_before_edit': 0, 'no_read_before': 0}

    agent_stats[agent]['sessions'] += 1

    for i, t in enumerate(tools):
        if t in ('edit', 'write'):
            agent_stats[agent]['edits_total'] += 1

            # Read before?
            if i > 0 and any(tools[j] == 'read' for j in range(max(0, i-3), i)):
                agent_stats[agent]['read_before_edit'] += 1
            else:
                agent_stats[agent]['no_read_before'] += 1

            # Verify after? (bash or read within next 3 steps)
            remaining = tools[i+1:]
            if remaining and any(r in ('bash', 'read') for r in remaining[:3]):
                agent_stats[agent]['verify_after'] += 1
            else:
                agent_stats[agent]['no_verify'] += 1

print(f"{'Agent':<12} {'Sessions':<10} {'Edits':<8} {'ReadBefore':<12} {'NoRead':<8} {'VerifyAfter':<13} {'NoVerify':<10}")
print("-" * 75)
for agent, stats in sorted(agent_stats.items(), key=lambda x: -x[1]['edits_total']):
    print(f"{agent:<12} {stats['sessions']:<10} {stats['edits_total']:<8} {stats['read_before_edit']:<12} {stats['no_read_before']:<8} {stats['verify_after']:<13} {stats['no_verify']:<10}")
EOF

# Let me look specifically at sessions that re-do work already done
# This is the "redundant work" / "idempotent dispatch" pattern
python3 << 'EOF'
import json, os

sessions_dir = ".state/sessions/history"
sids = sorted(os.listdir(sessions_dir), key=lambda x: os.path.getmtime(f"{sessions_dir}/{x}"), reverse=True)[:60]

redundant = []
for sid in sids:
    jsonl = f"{sessions_dir}/{sid}/session.jsonl"
    if not os.path.exists(jsonl):
        continue

    with open(jsonl) as fh:
        for line in fh:
            try:
                d = json.loads(line)
                if d.get('role') == 'assistant' and d.get('content'):
                    for item in (d.get('content') or []):
                        if item.get('type') == 'toolCall' and item.get('name') == 'finish':
                            args = json.loads(item.get('arguments','{}')) if isinstance(item.get('arguments'), str) else item.get('arguments',{})
                            summary = args.get('summary', '')
                            if any(x in summary.lower() for x in ['already done', 'already applied', 'already fixed', 'already correct', 'already dispatched', 'no changes needed', 'previous session']):
                                meta = f"{sessions_dir}/{sid}/meta.json"
                                with open(meta) as f:
                                    m = json.load(f)
                                agent = m.get('agent', '')
                                redundant.append((sid, agent, summary[:150]))
            except:
                pass

print(f"Redundant work sessions (detected 'already done' in finish summary): {len(redundant)}")
for sid, agent, summary in redundant:
    print(f"\n  {sid} agent={agent}")
    print(f"  {summary}")
EOF

